INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES (2, 1000, 2, 3000, 2, "vo_minigame_1013_icon_2_002_001", 1, "訓練はまだ\nここからですわ", "vo_minigame_1013_icon_1_002_001", "調子が上がって\nきたなっ");
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES (2, 5000, 2, 3000, 2, "vo_minigame_1013_icon_2_003_001", 2, "クスクス、悪くない\n流れですわね", "vo_minigame_1013_icon_1_003_001", "ほらほら、\nまだいけるだろ？");
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES (2, 10000, 3, 3000, 2, "vo_minigame_1013_icon_2_004_001", 3, "すばらしい\n記録ですわ", "vo_minigame_1013_icon_1_004_001", "へへっ、おまえら\nやるじゃねえか！");
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES (3, 10000, 3, 3000, 2, "vo_minigame_1013_icon_2_005_001", 4, "乗りに乗って\nいますわね", "vo_minigame_1013_icon_1_005_001", "あたしたちはまだ\n止まらねえぜ！");
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES (3, 10000, 3, 3000, 2, "vo_minigame_1013_icon_2_005_002", 5, "まだまだ行きます\nついてきなさい", "vo_minigame_1013_icon_1_005_002", "見てろよ！\nマコト班の快進撃だ！");
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES (3, 10000, 3, 3000, 2, "vo_minigame_1013_icon_2_005_003", 6, "エリコ班の\n本領発揮ですわ！", "vo_minigame_1013_icon_1_005_003", "うおぉぉっ！\n絶好調だぜ！");
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES (4, 0, 3, 3000, 2, "vo_minigame_1013_icon_2_006_001", 7, "ここからは\n前人未到の領域です！", "vo_minigame_1013_icon_1_006_001", "どこまで行けるか\n楽しみだなっ！");
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES (5, 1, 4, 1000, 3, "vo_minigame_1013_icon_2_007_001", 8, "厄介でしたわ…", "vo_minigame_1013_icon_1_007_001", "まだ諦めんなよっ");
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES (5, 1, 4, 1000, 3, "vo_minigame_1013_icon_2_007_002", 9, "油断大敵です", "vo_minigame_1013_icon_1_007_002", "冷やっとしたぜ…！");
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES (5, 1, 4, 1000, 3, "vo_minigame_1013_icon_2_007_003", 10, "忌々しいっ…", "vo_minigame_1013_icon_1_007_003", "弱音を吐くなっ");
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES (6, 99, 3, 1500, 4, "vo_minigame_1013_icon_2_008_001", 11, "大所帯ですわね", "vo_minigame_1013_icon_1_008_001", "マコト班集合！");
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES (6, 99, 3, 1500, 4, "vo_minigame_1013_icon_2_008_002", 12, "エリコ班へようこそ", "vo_minigame_1013_icon_1_008_002", "連携してくぞ！");
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES (8, 0, 6, 3000, 1, "vo_minigame_1013_icon_2_020_001", 13, "ナナカちゃんに\nお任せあれ", "vo_minigame_1013_icon_1_020_001", "みんなに力を！");
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES (9, 0, 7, 3000, 1, "vo_minigame_1013_icon_2_022_001", 14, "はっはっは！\n任せろ！", "vo_minigame_1013_icon_1_022_001", "任せてくれたまえ");
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES (10, 0, 8, 3000, 1, "vo_minigame_1013_icon_2_023_001", 15, "どんどんいくわよ", "vo_minigame_1013_icon_1_023_001", "ほな、いきまひょか");
